import re, glob, os

os.chdir('/root/trace-verdict-study/docs/paper')

# Extract all cite keys from tex files (citep, citet, cite, citealt, etc.)
cite_keys = set()
cite_map = {}
for f in sorted(glob.glob('*.tex')):
    text = open(f).read()
    fkeys = set()
    for m in re.findall(r'\\cite[tp]?\{([^}]+)\}', text):
        for k in m.split(','):
            k = k.strip()
            cite_keys.add(k)
            fkeys.add(k)
    if fkeys:
        cite_map[f] = sorted(fkeys)

# Extract all bib keys and entries
bib_text = open('references.bib').read()
bib_entries = {}
for m in re.finditer(r'@(\w+)\{(\w+),\s*(.*?)(?=\n@|\Z)', bib_text, re.DOTALL):
    etype, key, body = m.groups()
    bib_entries[key] = {'type': etype, 'body': body}

def parse_fields(body):
    fields = {}
    for fm in re.finditer(r'(\w+)\s*=\s*\{([^}]*)\}', body):
        fields[fm.group(1).lower()] = fm.group(2).strip()
    return fields

pass_count = 0
warn_count = 0
fail_count = 0
issues_list = []

# 1. Cross-reference check
missing = cite_keys - set(bib_entries.keys())
orphans = set(bib_entries.keys()) - cite_keys

for k in sorted(missing):
    fail_count += 1
    issues_list.append('FAIL [missing-bib]: {} cited but has no bib entry'.format(k))

for k in sorted(orphans):
    warn_count += 1
    issues_list.append('WARN [orphan]: {} in bib but never cited'.format(k))

# 2. Field completeness
for key in sorted(bib_entries.keys()):
    entry = bib_entries[key]
    fields = parse_fields(entry['body'])
    problems = []
    for req in ['title', 'author', 'year']:
        if req not in fields:
            problems.append('missing ' + req)
    if entry['type'] == 'inproceedings' and 'booktitle' not in fields:
        problems.append('missing booktitle')
    if entry['type'] == 'article' and 'journal' not in fields:
        problems.append('missing journal')
    for f, v in fields.items():
        if any(x in v for x in ['TODO', 'XXX', 'PLACEHOLDER']) or v == '':
            problems.append('placeholder in ' + f)
    if 'year' in fields:
        try:
            y = int(fields['year'])
            if y < 2015 or y > 2027:
                problems.append('suspicious year {}'.format(y))
        except:
            problems.append('non-numeric year')
    if problems:
        fail_count += 1
        issues_list.append('FAIL [fields]: {} -- {}'.format(key, '; '.join(problems)))
    else:
        pass_count += 1

# 3. Type mismatches (article with conference journal, or vice versa)
for key in sorted(bib_entries.keys()):
    entry = bib_entries[key]
    fields = parse_fields(entry['body'])
    if entry['type'] == 'article' and 'journal' in fields:
        j = fields['journal'].lower()
        if any(x in j for x in ['proceedings', 'conference', 'workshop', 'iclr', 'icml', 'neurips', 'emnlp', 'acl']):
            if 'arxiv' not in j:
                warn_count += 1
                issues_list.append('WARN [type-mismatch]: {} is @article but journal looks like a venue: "{}"'.format(key, fields['journal']))

# 4. ArXiv-only check
for key in sorted(bib_entries.keys()):
    entry = bib_entries[key]
    fields = parse_fields(entry['body'])
    if entry['type'] == 'article' and 'journal' in fields and 'arxiv' in fields['journal'].lower():
        warn_count += 1
        issues_list.append('WARN [arxiv-only]: {} -- still listed as arXiv preprint (check if published)'.format(key))

# 5. Author spot check
for key in sorted(bib_entries.keys()):
    fields = parse_fields(bib_entries[key]['body'])
    if 'author' in fields:
        author = fields['author']
        if 'et al' in author.lower():
            warn_count += 1
            issues_list.append('WARN [author]: {} -- contains "et al" in author field'.format(key))

# Print report
print('=' * 60)
print('REFERENCE AUDIT REPORT')
print('=' * 60)
print()
print('Bib entries: {}'.format(len(bib_entries)))
print('Cite keys:   {}'.format(len(cite_keys)))
print()

print('--- Citation Source Map ---')
for f, keys in sorted(cite_map.items()):
    print('  {}: {}'.format(f, ', '.join(keys)))
print()

print('--- Issues ---')
for issue in issues_list:
    print(issue)
if not issues_list:
    print('(none)')
print()

print('--- Summary ---')
print('PASS: {} (all required fields present, no issues)'.format(pass_count))
print('WARN: {} (non-critical, worth reviewing)'.format(warn_count))
print('FAIL: {} (must fix)'.format(fail_count))
